def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Each straight 5-bar extends the adjacent motif across its own span.
    # Vertical bars copy a multi-cell horizontal motif to the right.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 5]
        for rows in _runs(rows):
            if len(rows) < 2 or c + 1 >= w:
                continue
            r1 = rows[-1]
            seed = r1 if any(grid[r1][cc] != 0 for cc in range(c + 1, w)) else r1 - 1
            if seed < 0 or grid[seed][c + 1] == 0:
                continue
            width = 0
            while c + 1 + width < w and grid[seed][c + 1 + width] != 0:
                width += 1
            start = seed
