                start -= 1
            motif = [grid[rr][c + 1:c + 1 + width] for rr in range(start, seed + 1)]
            for rr in rows:
                out[rr][c + 1:c + 1 + width] = motif[(rr - start) % len(motif)][:]

    # Horizontal bars copy the color sequence immediately below their left end.
    for r in range(h - 1):
        cols = [c for c in range(w) if grid[r][c] == 5]
        for cols in _runs(cols):
            if len(cols) < 2 or grid[r + 1][cols[0]] == 0:
